/**
 * Applies drizzle migrations (./drizzle, generated by `npm run db:generate`) and the RLS DDL.
 * Run as the OWNER role (DATABASE_URL_MIGRATE), never as jiat_app.
 */
import { sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';
import { rlsStatements } from './rls.js';

async function main(): Promise<void> {
  const url = process.env['DATABASE_URL_MIGRATE'] ?? process.env['DATABASE_URL'];
  if (!url) throw new Error('DATABASE_URL_MIGRATE (atau DATABASE_URL) harus diisi.');
  const client = postgres(url, { max: 1, onnotice: () => {} });
  const db = drizzle(client);
  try {
    await migrate(db, { migrationsFolder: './drizzle' });
    for (const stmt of rlsStatements()) await db.execute(sql.raw(stmt));
    const [row] = await db.execute<{ n: string }>(sql`SELECT count(*)::text AS n FROM pg_policies WHERE schemaname = 'public'`);
    console.log(`Migrasi selesai. Policy RLS aktif: ${row?.n ?? '?'}`);
  } finally {
    await client.end({ timeout: 5 });
  }
}

main().catch((e: unknown) => {
  console.error('Migrasi gagal:', e instanceof Error ? e.message : e);
  process.exitCode = 1;
});
